// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 unlockTime, uint256 withdrawAmount) public {
        vm.assume(caller != address(0));
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: depositAmount}(abi.encodeWithSignature("Put(uint256)", unlockTime));
        // If deposit succeeded, we want to test with non-zero balance; otherwise, balance may remain 0
        bool deposited = success && depositAmount > 0;
        vm.prank(caller);
        (bool reverted, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));
        if (!deposited) {
            assertTrue(reverted, "Collect should revert when caller has no balance");
        }
    }
}

